        CHECK(result.classified);
        CHECK(result.kind == PelicanStudio::GraphCanvasScene::RedrawClass::chrome);
        CHECK(result.rebuilds == 1);
        CHECK(result.redrawn.empty());
        CHECK(result.refused == (1 << 13));
        CHECK(result.chrome_detail2 == 2);
